//! Stdlib `.rx` sources embedded into the ruxen binary via
//! `include_str!`. Makes the toolchain self-contained — no need to
//! ship `library/std/` next to the executable or set
//! `RUXEN_STDLIB_PATH` after `cargo install`.
//!
//! Both tables are generated by `compiler/ruxen_core/build.rs` from its
//! ordered package list and the `library/std/` tree, together with
//! [`BOOTSTRAP_FILES`](crate::resolve::bootstrap::BOOTSTRAP_FILES), so
//! they cannot drift from each other. Adding a package is one line in
//! that list; adding a sibling `.rx` file needs no edit at all.
//!
//! Filesystem reads still work — `bootstrap.rs::run_bootstrap_with_files`
//! prefers `RUXEN_STDLIB_PATH` / a passed-in path override when one
//! is provided, so stdlib hackers can edit `.rx` files and re-run
//! without recompiling the compiler.

/// Embedded stdlib sources, keyed by the same relative path the
/// filesystem loader uses (`"<pkg>/src/lib.rx"`), in
/// `BOOTSTRAP_FILES` order. Generated by `build.rs`.
pub const BOOTSTRAP_EMBEDDED: &[(&str, &str)] =
    include!(concat!(env!("OUT_DIR"), "/bootstrap_embedded.rs"));

/// Look up an embedded stdlib source by its relative path. Returns
/// `None` if the file isn't in the table — the caller falls back to
/// filesystem reads.
pub fn embedded_source(rel: &str) -> Option<&'static str> {
    BOOTSTRAP_EMBEDDED
        .iter()
        .find(|(p, _)| *p == rel)
        .map(|(_, src)| *src)
}

/// Sibling `.rx` files baked in for multi-file stdlib packages.
/// Keyed by the package's `lib.rx` relative path. The slice value
/// holds `(filename, source)` pairs for every sibling, sorted by
/// filename; lib.rx itself is fetched via [`embedded_source`].
/// Generated by `build.rs` from each package's `src/` directory.
pub const BOOTSTRAP_EMBEDDED_SIBLINGS: &[(&str, &[(&str, &str)])] =
    include!(concat!(env!("OUT_DIR"), "/bootstrap_embedded_siblings.rs"));

/// Multi-file package lookup. When the package has sibling files in
/// [`BOOTSTRAP_EMBEDDED_SIBLINGS`], returns the lib.rx source plus
/// every sibling so the caller can concatenate them the same way the
/// filesystem loader does. Returns `None` for single-file packages —
/// callers fall back to [`embedded_source`].
pub fn embedded_pkg_sources(rel: &str) -> Option<Vec<(&'static str, &'static str)>> {
    let siblings = BOOTSTRAP_EMBEDDED_SIBLINGS
        .iter()
        .find(|(p, _)| *p == rel)
        .map(|(_, s)| *s)?;
    let lib_src = embedded_source(rel)?;
    let mut out: Vec<(&'static str, &'static str)> = Vec::with_capacity(siblings.len() + 1);
    out.push(("lib.rx", lib_src));
    out.extend_from_slice(siblings);
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::resolve::bootstrap::BOOTSTRAP_FILES;

    fn std_root() -> std::path::PathBuf {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../library/std")
    }

    /// The generated tables cover every package on disk: each
    /// `library/std/<pkg>/src/lib.rx` is a `BOOTSTRAP_FILES` entry with a
    /// non-empty embedded source. Catches a package added to the tree but
    /// not to `build.rs`'s list, even when the build script did not rerun.
    #[test]
    fn bootstrap_files_cover_every_std_package_on_disk() {
        let mut on_disk: Vec<String> = std::fs::read_dir(std_root())
            .expect("read library/std")
            .flatten()
            .filter(|e| e.path().join("src/lib.rx").is_file())
            .filter_map(|e| e.file_name().into_string().ok())
            .map(|pkg| format!("{pkg}/src/lib.rx"))
            .collect();
        on_disk.sort();
        let mut listed: Vec<String> = BOOTSTRAP_FILES.iter().map(|r| r.to_string()).collect();
        listed.sort();
        assert_eq!(listed, on_disk, "BOOTSTRAP_FILES differs from library/std");
        for rel in BOOTSTRAP_FILES {
            assert!(
                embedded_source(rel).is_some_and(|src| !src.is_empty()),
                "no embedded source for `{rel}`"
            );
        }
    }

    /// The filesystem loader concatenates `lib.rx` with every sibling
    /// `.rx` in the package's `src/`; the embedded table must hold the
    /// same set, and each listed package's `lib.rx` must be embedded.
    #[test]
    fn multi_file_pkg_lib_present_when_siblings_listed() {
        for (lib_rel, _) in BOOTSTRAP_EMBEDDED {
            let src_dir = std_root().join(lib_rel).parent().unwrap().to_path_buf();
            let mut on_disk: Vec<String> = std::fs::read_dir(&src_dir)
                .unwrap_or_else(|e| panic!("read {}: {e}", src_dir.display()))
                .flatten()
                .filter_map(|e| e.file_name().into_string().ok())
                .filter(|n| n.ends_with(".rx") && n != "lib.rx")
                .collect();
            on_disk.sort();
            let mut listed: Vec<String> = BOOTSTRAP_EMBEDDED_SIBLINGS
                .iter()
                .find(|(p, _)| p == lib_rel)
                .map(|(_, sibs)| sibs.iter().map(|(n, _)| n.to_string()).collect())
                .unwrap_or_default();
            listed.sort();
            assert_eq!(
                listed,
                on_disk,
                "embedded siblings for `{lib_rel}` differ from {}",
                src_dir.display()
            );
        }
        for (lib_rel, _) in BOOTSTRAP_EMBEDDED_SIBLINGS {
            assert!(
                embedded_source(lib_rel).is_some(),
                "`{lib_rel}` lists siblings but its lib.rx is not in BOOTSTRAP_EMBEDDED"
            );
        }
    }

    #[test]
    fn embedded_source_lookup_finds_known_file() {
        assert!(embedded_source("core/src/lib.rx").is_some());
        assert!(embedded_source("io/src/lib.rx").is_some());
        assert!(embedded_source("nonexistent/src/lib.rx").is_none());
    }
}
